 "Customer-led":[[.40,.60],[.10,.25],[.10,.25],[.10,.25]],
 "Competitive/cost":[[.15,.30],[.25,.40],[.10,.25],[.25,.40]],
 "Broad/uncertain":[[.15,.40],[.15,.40],[.10,.35],[.10,.35]]
};
for (const [sc, ranges] of Object.entries(scenarios)) {
 let n=100000, first=[0,0,0], top2=[0,0,0];
 for(let i=0;i<n;i++){
  const raw=ranges.map(([a,b])=>a+rand()*(b-a)); const sum=raw.reduce((a,b)=>a+b,0); const w=raw.map(x=>x/sum);
  const vals=alts.map(a=>a.v.map(([lo,hi])=>lo+rand()*(hi-lo)));
  const scores=vals.map(v=>v.reduce((z,x,j)=>z+x*w[j],0));
  const ord=scores.map((v,j)=>[v,j]).sort((a,b)=>b[0]-a[0]);
  first[ord[0][1]]++; top2[ord[0][1]]++; top2[ord[1][1]]++;
 }
 text(`${sc}: top1 ${first.map(x=>(x/n*100).toFixed(1)+"%").join(", ")}; top2 ${top2.map(x=>(x/n*100).toFixed(1)+"%").join(", ")}`);
}

